// Atlas catalog: the 195 countries (193 UN member states + 2 UN observer states)
// and 16 special destinations, each with factual geographic data.
// Content status: "complete" = fully written destination, "preview" = partial, "coming" = à venir.
// Special destinations are described by their real status and never counted as sovereign states.
import type { AtlasTag, CatalogEntry, Continent, EnglishStatus } from "./types";

const VIRTUAL =
  "Découverte virtuelle et éducative ; ce contenu n'incite pas à s'y rendre. Consulte les conseils aux voyageurs officiels.";

type Opts = Partial<Pick<CatalogEntry, "status" | "statusNote" | "capitalNote" | "virtualOnly" | "virtualNote" | "books" | "content">>;

function c(
  id: string,
  iso2: string,
  nameFr: string,
  nameEn: string,
  continent: Continent,
  capital: string,
  lat: number,
  lon: number,
  languages: string[],
  english: EnglishStatus,
  tags: AtlasTag[],
  themes: string[],
  opts: Opts = {},
): CatalogEntry {
  const virtual = opts.virtualOnly ? { virtualOnly: true, virtualNote: opts.virtualNote ?? VIRTUAL } : {};
  return { id, iso2, nameFr, nameEn, continent, status: "sovereign", capital, lat, lon, languages, english, tags, themes, content: "coming", ...opts, ...virtual };
}
const V: Opts = { virtualOnly: true };

