export const CATALOG: CatalogEntry[] = [...EUROPE, ...ASIA, ...AFRICA, ...NORTH_AMERICA, ...SOUTH_AMERICA, ...OCEANIA, ...SPECIAL];

/** Number of countries in the 195 list (193 UN members + 2 observer states). */
export const SOVEREIGN_COUNT = CATALOG.filter((e) => e.status === "sovereign" || e.status === "observer").length;

const BY_ID = new Map(CATALOG.map((e) => [e.id, e]));
export function getCatalog(id: string): CatalogEntry | undefined {
  return BY_ID.get(id);
}

export const CONTINENT_LABEL: Record<Continent, string> = {
  europe: "Europe",
  asia: "Asie",
  africa: "Afrique",
  "north-america": "Amérique du Nord, centrale et Caraïbes",
  "south-america": "Amérique du Sud",
  oceania: "Océanie",
  antarctica: "Antarctique",
};

export function byContinent(): Record<Continent, CatalogEntry[]> {
  const out = { europe: [], asia: [], africa: [], "north-america": [], "south-america": [], oceania: [], antarctica: [] } as Record<Continent, CatalogEntry[]>;
  for (const e of CATALOG) out[e.continent].push(e);
  return out;
}
